mapper.select:
SELECT * FROM inspection.inspection_question_rule a WHERE 1 = 1
AND a.RULE_ID = #{params.RULE_ID}
AND a.RULE_FILE_NO like '%${params.RULE_FILE_NO}%'
AND a.RULE_FILE_NAME like '%${params.key_word}%' or a.RULE_FILE_CONTENT LIKE '%${params.key_word}%'
AND a.RULE_STATE = #{params.RULE_STATE}
ORDER BY RULE_FILE_NO, RULE_FILE_NAME, SORT LIMIT ${params.page},${params.rows}

SELECT * FROM inspection.inspection_question_rule a WHERE 1 = 1
AND a.RULE_ID = #{params.RULE_ID}
AND a.RULE_FILE_NO like '%${params.RULE_FILE_NO}%'
AND a.RULE_FILE_NAME like '%${params.key_word}%' or a.RULE_FILE_CONTENT LIKE '%${params.key_word}%'
AND a.RULE_STATE = #{params.RULE_STATE}
AND a.SORT = #{params.SORT}
ORDER BY RULE_FILE_NO, RULE_FILE_NAME, SORT

SELECT a.*,c.QUESTION_ID,b.ID FROM inspection.inspection_question_rule a, inspection.inspection_question_rule_relation b, inspection.inspection_question_bank c WHERE 1 = 1 and a.RULE_ID = b.RULE_ID and c.QUESTION_ID = b.QUESTION_ID
AND c.QUESTION_ID = #{params.QUESTION_ID}
AND a.RULE_ID = #{params.RULE_ID}
AND a.RULE_FILE_NO like '%${params.RULE_FILE_NO}%'
AND a.RULE_FILE_NAME like '%${params.key_word}%' or a.RULE_FILE_CONTENT LIKE '%${params.key_word}%'
AND a.RULE_STATE = #{params.RULE_STATE}

SELECT count(*) FROM inspection.inspection_question_rule a WHERE 1 = 1
AND a.RULE_ID = #{params.RULE_ID}
AND a.RULE_FILE_NO like '%${params.RULE_FILE_NO}%'
AND a.RULE_FILE_NAME like '%${params.key_word}%' or a.RULE_FILE_CONTENT LIKE '%${params.key_word}%'
AND a.RULE_STATE = #{params.RULE_STATE}

SELECT * FROM inspection.inspection_question_rule a WHERE 1 = 1
AND a.RULE_ID != #{params.RULE_ID}
AND a.RULE_FILE_CONTENT = #{params.RULE_FILE_CONTENT}

mapper.update:
UPDATE inspection.inspection_question_rule SET
SORT = SORT + 1
WHERE SORT >=  #{params.SORT}
and RULE_FILE_NO = #{params.RULE_FILE_NO}
